/**
 * Explicit initial installation. Existing tables cause a failure and rollback.
 * Evolving a populated database requires a reviewed application migration.
 * Use the same prefix when loading StorageManifest::withPrefix().
 */
return static function (\PDO $database, string $prefix = ''): void {
    if ($database->getAttribute(\PDO::ATTR_DRIVER_NAME) !== 'sqlite') {
        throw new \InvalidArgumentException('This installer requires PDO SQLite.');
    }
    if ($prefix !== '' && !preg_match('/^[A-Za-z_][A-Za-z0-9_]*$/D', $prefix)) {
        throw new \InvalidArgumentException('Invalid SQLite table prefix.');
    }
    if ($database->inTransaction()) {
        throw new \LogicException('Run the initial installer outside an existing transaction.');
    }
    $database->exec('PRAGMA foreign_keys = ON');
    $table = static fn (string $name): string => '"' . $prefix . $name . '"';
    $statements = [
        'CREATE TABLE ' . $table('clog_inventory') . ' (
    ' . '"id" INTEGER PRIMARY KEY AUTOINCREMENT' . ',
    ' . '"created_at" TEXT NOT NULL' . ',
    ' . '"updated_at" TEXT NOT NULL' . ',
    ' . '"post_id" INTEGER' . ',
    ' . '"name" TEXT NOT NULL CHECK (length("name") <= 200)' . ',
    ' . '"date_added" TEXT NOT NULL' . ',
    ' . '"date_expiry" TEXT' . ',
    ' . '"item_id" INTEGER' . ' REFERENCES ' . $table('clog_item') . '("id") ON DELETE RESTRICT' . ',
    ' . '"location_id" INTEGER' . ' REFERENCES ' . $table('clog_location') . '("id") ON DELETE RESTRICT' . '
)',
        'CREATE UNIQUE INDEX ' . $table('clog_inventory_post_id_uniq') . ' ON ' . $table('clog_inventory') . ' ("post_id")',
        'CREATE INDEX ' . $table('clog_inventory_item_id_idx') . ' ON ' . $table('clog_inventory') . ' ("item_id")',
        'CREATE INDEX ' . $table('clog_inventory_location_id_idx') . ' ON ' . $table('clog_inventory') . ' ("location_id")',
        'CREATE TABLE ' . $table('clog_inventory_site') . ' (
    ' . '"inventory_id" INTEGER NOT NULL' . ' REFERENCES ' . $table('clog_inventory') . '("id") ON DELETE RESTRICT' . ',
    ' . '"site_id" INTEGER NOT NULL' . ' REFERENCES ' . $table('clog_site') . '("id") ON DELETE RESTRICT' . '
)',
        'CREATE UNIQUE INDEX ' . $table('clog_inventory_site_pair_uniq') . ' ON ' . $table('clog_inventory_site') . ' ("inventory_id", "site_id")',
        'CREATE INDEX ' . $table('clog_inventory_site_site_id_idx') . ' ON ' . $table('clog_inventory_site') . ' ("site_id")',
        'CREATE TABLE ' . $table('clog_item') . ' (
    ' . '"id" INTEGER PRIMARY KEY AUTOINCREMENT' . ',
    ' . '"created_at" TEXT NOT NULL' . ',
    ' . '"updated_at" TEXT NOT NULL' . ',
    ' . '"post_id" INTEGER' . ',
    ' . '"name" TEXT NOT NULL CHECK (length("name") <= 200)' . ',
    ' . '"barcode" TEXT CHECK (length("barcode") <= 64)' . ',
    ' . '"default_expiry_unit" TEXT CHECK ("default_expiry_unit" IN (\'days\', \'months\'))' . ',
    ' . '"default_expiry_value" INTEGER' . '
)',
        'CREATE UNIQUE INDEX ' . $table('clog_item_post_id_uniq') . ' ON ' . $table('clog_item') . ' ("post_id")',
        'CREATE INDEX ' . $table('clog_item_name_idx') . ' ON ' . $table('clog_item') . ' ("name")',
        'CREATE UNIQUE INDEX ' . $table('clog_item_barcode_uniq') . ' ON ' . $table('clog_item') . ' ("barcode")',
        'CREATE TABLE ' . $table('clog_location') . ' (
    ' . '"id" INTEGER PRIMARY KEY AUTOINCREMENT' . ',
    ' . '"created_at" TEXT NOT NULL' . ',
    ' . '"updated_at" TEXT NOT NULL' . ',
    ' . '"post_id" INTEGER' . ',
    ' . '"name" TEXT NOT NULL CHECK (length("name") <= 200)' . '
)',
        'CREATE UNIQUE INDEX ' . $table('clog_location_post_id_uniq') . ' ON ' . $table('clog_location') . ' ("post_id")',
        'CREATE UNIQUE INDEX ' . $table('clog_location_name_uniq') . ' ON ' . $table('clog_location') . ' ("name")',
        'CREATE TABLE ' . $table('clog_location_sites') . ' (
    ' . '"location_id" INTEGER NOT NULL' . ' REFERENCES ' . $table('clog_location') . '("id") ON DELETE RESTRICT' . ',
    ' . '"site_id" INTEGER NOT NULL' . ' REFERENCES ' . $table('clog_site') . '("id") ON DELETE RESTRICT' . '
)',
        'CREATE UNIQUE INDEX ' . $table('clog_location_sites_pair_uniq') . ' ON ' . $table('clog_location_sites') . ' ("location_id", "site_id")',
        'CREATE INDEX ' . $table('clog_location_sites_site_id_idx') . ' ON ' . $table('clog_location_sites') . ' ("site_id")',
        'CREATE TABLE ' . $table('clog_site') . ' (
    ' . '"id" INTEGER PRIMARY KEY AUTOINCREMENT' . ',
    ' . '"name" TEXT NOT NULL CHECK (length("name") <= 200)' . '
)',
        'CREATE UNIQUE INDEX ' . $table('clog_site_name_uniq') . ' ON ' . $table('clog_site') . ' ("name")',
        'CREATE TABLE ' . $table('clog_user') . ' (
    ' . '"id" INTEGER PRIMARY KEY AUTOINCREMENT' . ',
    ' . '"created_at" TEXT NOT NULL' . ',
    ' . '"updated_at" TEXT NOT NULL' . ',
    ' . '"post_id" INTEGER' . ',
    ' . '"bio" TEXT' . '
)',
        'CREATE UNIQUE INDEX ' . $table('clog_user_post_id_uniq') . ' ON ' . $table('clog_user') . ' ("post_id")',
    ];
    $database->beginTransaction();
    try {
        foreach ($statements as $sql) {
            if ($database->exec($sql) === false) {
                $detail = $database->errorInfo()[2] ?? null;
                throw new \RuntimeException('SQLite schema installation failed: ' . (is_string($detail) ? $detail : 'unknown error'));
            }
        }
        $database->commit();
    } catch (\Throwable $error) {
        $database->rollBack();
        throw $error;
    }
};
